#!/usr/bin/env python3
"""One-shot packaging of already executed review2 results, without promoting scope."""
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,re
B=Path(__file__).resolve().parent; R=B.parents[2]
def read(n):return json.loads((B/n).read_text())
controls,frozen,bounds,geom,hunt,consumer,pendants,lean,v2=[read(n) for n in ['controls.json','frozen.json','boundaries.json','geometry.json','local-hunt.json','consumers.json','pendant-internals.json','lean.json','lean-v2.json']]
assert frozen['optimum']==2 and all(x['counts']==[2,3,2] for x in frozen['rows'])
assert geom['cases']==15600 and pendants['cases']==16384
assert hunt['anchor']==44862 and hunt['empty_repairs']==5070 and hunt['minimum_fragments']==9897
assert consumer['ordinary_c']==consumer['swapped_a']==36 and consumer['two_stage_minimum_cases']==38
assert lean['positive_modules']==8 and lean['negative_controls_rejected']==2
assert sum(x['returncode']==0 for x in v2['rows'])==4 and sum(x['expected_rejection'] for x in v2['rows'])==1
bugs=[]
for d in bounds:
 spec=json.loads((B.parent/'edge_route'/d['fixture']).read_text())
 compound=d['fixture'].startswith('compound')
 bugs.append({'id':'compound-empty-unrestricted-normalization' if compound else 'partial-is-not-full-normalization','status':'executed-known-broader-statement-failure','failing_claim':'arbitrary compound E can normalize without an anchor' if compound else 'restoring a selected proper subset of path cuts is automatically equivalent to full normalization','instance':{'T1':spec['T1'],'T2':spec['T2'],'rho':'labelled unary root added','E':d['E']},'before_AF':True,'after_AF':d['full_AF'] if compound else d['partial_AF'],'predicted_by_false_claim':True,'actual':False,'cut_count':d['cut_count'],'optimum':d['optimum'],'result_cutset':d['full_normalized'] if compound else d['partial_restoration'],'in_minimum_consumer_regime':False,'receipt':str((B/'boundaries.json').resolve()),'replay':'fresh_graph.py boundaries'})
bugs.append({'id':'suppressed-corridor-unchanged-claim','status':'deliberate-negative-control-rejected','instance':'frozen 2B fixture after cutting B','claimed_unchanged_original_edge':frozen['suppressed_corruption_rejected'],'predicted':True,'actual':False,'receipt':str((B/'frozen.json').resolve()),'replay':'fresh_graph.py frozen'})
(B/'bugs.json').write_text(json.dumps(bugs,indent=2)+'\n')
now=datetime.now(timezone.utc).isoformat()
verdict={'status':'REVIEWED-PROSE-LOCAL-CHAIN; GENERAL-LIFT-OPEN','completed_at':now,'review_target':str((B.parent/'SECOND-REVIEW-TARGET.md').resolve()),'report':str((B/'REPORT.md').resolve()),'independent_derivation':str((B/'INDEPENDENT-DERIVATION.md').resolve()),'claimed_scope':'Restricted N_anchor and strict empty-common-subtree repair; arbitrary-K corridor-specific cut/yield/fragment transport; two-exchange local minimum witness and ordinary/swapped A2BC fixed-forest exchanges; separately rebuilt scoped Lean constituents.','new_in_regime_counterexamples':[],'reproduced_broader_failures':bugs[:2],'independence':{'author_or_prior_reviewer_evaluator_read':False,'author_or_prior_reviewer_evaluator_imported':False,'own_derivation_before_proof_reports':True,'frozen_and_boundary_controls_before_proof_reports':True,'initial_15600_geometry_before_proof_reports':True,'exact_final_ID_strengthening':'added and rerun after proof reports; initial unchanged-edge identity checks preceded proof reports','shared_layers':['pinned theorem/fixture data','primary thesis conventions','Python standard library'],'initial_code_hash_frozen_before_proof_read':False,'version2_read_order':'completed receipt then report, after independent derivation and initial full geometry reconstruction'},'counts':{'arbitrary_K_cases':geom['cases'],'arbitrary_K_graphs':geom['graphs'],'empty_u_or_x_fragment_cases':geom['empty_root_cases'],'pendant_internal_family':pendants,'local_hunt':hunt,'consumers':{k:v for k,v in consumer.items() if k!='first_exchange'}},'formal':{'original_positive_modules':8,'original_negative_controls_rejected':2,'v2_positive_modules':4,'v2_negative_controls_rejected':1,'only_standard_axioms':True,'no_sorry_admit_custom_axioms_native_decide':True,'original_receipt':str((B/'lean.json').resolve()),'v2_receipt':str((B/'lean-v2.json').resolve()),'universal_AF_Lean_theorem':False,'v2_graph_encoding_formalized':False},'smallest_remaining_general_obligation':'For each allowed reduction/promising child, lift an optimal residual completion to a minimum original-current-edge AF cutset containing selected branch cuts with additive count; allow designated protected origin selection on each cut compressed path, and preserve the corresponding later root-sibling replacement.','excluded':['general branch optimum lifting','protected-origin lifting','later root-sibling transport','marked-state induction','algorithm correctness','runtime','convention transfer','novelty'],'limitations':['finite families do not prove universal statements','supplemental pendant-internal family was bounded but not separately piloted at its larger size','initial evaluator hash was not frozen before proof reading; order retained in workfile/tool calls/logs','repository-wide bootloops-check not run','no external bibliography audit','bootloops Python lacks fitz; bundled Poppler used'],'owned_files_only':True,'aggregate_theorem_counts_modified':False,'all_local':True}
(B/'verdict.json').write_text(json.dumps(verdict,indent=2)+'\n')
manifest={str(p.relative_to(B)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(B.rglob('*')) if p.is_file() and p.name!='files.sha256.json' and '__pycache__' not in p.parts}
(B/'files.sha256.json').write_text(json.dumps(manifest,indent=2)+'\n')
# The only external outputs are the three paths assigned by the review target.
results=R/'results';progress=R/'progress';assert results.exists() and progress.exists(),R
(results/'thesis-correctness-repair-review2-verdict.json').write_text(json.dumps(verdict,indent=2)+'\n')
(results/'thesis-correctness-repair-review2-bugs.json').write_text(json.dumps(bugs,indent=2)+'\n')
(progress/'thesis-correctness-repair-review2.json').write_text(json.dumps({'status':'completed-local-review-general-lift-open','updated_at':now,'report':str((B/'REPORT.md').resolve()),'verdict':str((results/'thesis-correctness-repair-review2-verdict.json').resolve()),'independent_frozen_reconstruction':True,'original_lean_rebuilt':True,'v2_lean_rebuilt':True,'general_correctness_proved':False},indent=2)+'\n')
print(json.dumps({'status':verdict['status'],'files_hashed':len(manifest),'result':str((results/'thesis-correctness-repair-review2-verdict.json').resolve())}))
